script:
test("any partial hour rounds up", function () {
  var r = code.billableObservationHours({ admission: "2026-01-10 08:00", discharge: "2026-01-10 10:01" });
  assert.deepEqual(r, { status: "ok", elapsedMinutes: 121, roundedHours: 3, billableHours: 3, flags: [] });
});

test("spring-forward real elapsed, exact hours unchanged", function () {
  var r = code.billableObservationHours({ admission: "2026-03-07 22:00", discharge: "2026-03-08 22:00" });
  assert.deepEqual(r, { status: "ok", elapsedMinutes: 1380, roundedHours: 23, billableHours: 23, flags: [] });
});

test("fall-back real elapsed", function () {
  var r = code.billableObservationHours({ admission: "2026-10-31 22:00", discharge: "2026-11-01 22:00" });
  assert.deepEqual(r, { status: "ok", elapsedMinutes: 1500, roundedHours: 25, billableHours: 25, flags: [] });
});

test("cap far above 48", function () {
  var r = code.billableObservationHours({ admission: "2026-01-10 08:00", discharge: "2026-01-13 08:00" });
  assert.deepEqual(r, { status: "ok", elapsedMinutes: 4320, roundedHours: 72, billableHours: 48, flags: [] });
});

test("one whole hour under the cap", function () {
  var r = code.billableObservationHours({ admission: "2026-01-10 08:00", discharge: "2026-01-12 07:00" });
  assert.deepEqual(r, { status: "ok", elapsedMinutes: 2820, roundedHours: 47, billableHours: 47, flags: [] });
});

test("elapsed exactly 48 hours", function () {
  var r = code.billableObservationHours({ admission: "2026-01-10 08:00", discharge: "2026-01-12 08:00" });
  assert.deepEqual(r, { status: "ok", elapsedMinutes: 2880, roundedHours: 48, billableHours: 48, flags: [] });
});

test("one real minute past 48 hours, round then cap", function () {
  var r = code.billableObservationHours({ admission: "2026-01-10 08:00", discharge: "2026-01-12 08:01" });
  assert.deepEqual(r, { status: "ok", elapsedMinutes: 2881, roundedHours: 49, billableHours: 48, flags: [] });
});

test("zero elapsed is valid and stays 0", function () {
  var r = code.billableObservationHours({ admission: "2026-04-01 00:00", discharge: "2026-04-01 00:00" });
  assert.deepEqual(r, { status: "ok", elapsedMinutes: 0, roundedHours: 0, billableHours: 0, flags: [] });
});

test("smallest step, 1 minute, on a leap day", function () {
  var r = code.billableObservationHours({ admission: "2028-02-28 23:59", discharge: "2028-02-29 00:00" });
  assert.deepEqual(r, { status: "ok", elapsedMinutes: 1, roundedHours: 1, billableHours: 1, flags: [] });
});

test("29 minutes, just below halfway, still rounds up", function () {
  var r = code.billableObservationHours({ admission: "2026-12-31 23:31", discharge: "2027-01-01 00:00" });
  assert.deepEqual(r, { status: "ok", elapsedMinutes: 29, roundedHours: 1, billableHours: 1, flags: [] });
});

test("31 minutes, just above halfway, rounds up", function () {
  var r = code.billableObservationHours({ admission: "2026-01-31 23:29", discharge: "2026-02-01 00:00" });
  assert.deepEqual(r, { status: "ok", elapsedMinutes: 31, roundedHours: 1, billableHours: 1, flags: [] });
});

test("exact one hour unchanged inside EDT", function () {
  var r = code.billableObservationHours({ admission: "2026-07-15 14:00", discharge: "2026-07-15 15:00" });
  assert.deepEqual(r, { status: "ok", elapsedMinutes: 60, roundedHours: 1, billableHours: 1, flags: [] });
});

test("ambiguous local time on the first field", function () {
  var r = code.billableObservationHours({ admission: "2026-11-01 01:30", discharge: "2026-11-01 03:00" });
  assert.equal(r.status, "ambiguous");
  assert.equal(r.elapsedMinutes, null);
  assert.equal(r.roundedHours, null);
  assert.equal(r.billableHours, null);
  assert.match(r.flags.join(" "), /admission/);
  assert.ok(!/discharge/.test(r.flags.join(" ")));
});

test("nonexistent local time on the last field", function () {
  var r = code.billableObservationHours({ admission: "2026-03-08 01:30", discharge: "2026-03-08 02:30" });
  assert.equal(r.status, "nonexistent");
  assert.equal(r.elapsedMinutes, null);
  assert.equal(r.roundedHours, null);
  assert.equal(r.billableHours, null);
  assert.match(r.flags.join(" "), /discharge/);
  assert.ok(!/admission/.test(r.flags.join(" ")));
});

test("discharge one minute earlier than admission", function () {
  var r = code.billableObservationHours({ admission: "2026-01-10 08:00", discharge: "2026-01-10 07:59" });
  assert.equal(r.status, "invalid");
  assert.equal(r.elapsedMinutes, null);
  assert.equal(r.roundedHours, null);
  assert.equal(r.billableHours, null);
  assert.match(r.flags.join(" "), /discharge/);
  assert.ok(!/admission/.test(r.flags.join(" ")));
});

test("unknown field", function () {
  assert.throws(function () {
    code.billableObservationHours({ admission: "2026-01-10 08:00", discharge: "2026-01-10 09:00", ward: "x" });
  }, /^unknown field: ward$/);
});
